from common import accept,read
c=read('candidates.json')
def food(id,prefix=''):
    s=c['rr.p0'+id].removeprefix(prefix)
    for a,b in {'камней':'стоунов','камня':'стоуна','камень':'стоун','КОН':'ТЕЛ','с.п.':'см','человекообразных существ':'существ размером с человека','следопытства':'Выслеживания','навыка поиска':'навыка Собирательства','навыком выживания':'навыком Выживание','[[Survival (О) Выживание]]':'Выживание','[[Ancillary activities - Вспомогательное дело|вспомогательным действием]]':'вспомогательной деятельностью','[[Dedicated activities - Целенаправленное дело]]':'целенаправленная деятельность','скорость экспедиции':'экспедиционная скорость','скорости экспедиции':'экспедиционной скорости'}.items():s=s.replace(a,b)
    return s
frigid='Мороз наступает при температуре 0° F и ниже. Экспедиционная скорость искателей приключений сокращается вдвое, а собирательство невозможно. Если персонаж обходится без защитной одежды более шести ходов или промокает, он становится **Переохлаждённым**. Переохлаждённый не может совершать форсированный марш или естественно залечивать раны и теряет 1d3 ТЕЛ каждый час, пока состояние не закончится или ТЕЛ не упадёт до 0, после чего он умирает. Состояние заканчивается, если персонаж не менее часа греется у костра или другого большого источника тепла. В конце дня, когда персонаж переохладился или получил урон холодом, он должен сделать спасбросок от смерти. При провале он получает обморожение и должен бросить 1d6 по строке 16–20 таблицы «Смертельные раны — холод» (стр. 520), рискуя лишиться пальцев рук или ног, уха или даже носа. В мороз отдых невозможен без защитной одежды или одеял и одновременно костра или другого большого источника тепла. После семи дней мороза подряд вероятность заболеть составляет 10%, если персонаж не обладает неуязвимостью к болезням. Устойчивость или неуязвимость к урону холодом отменяет все перечисленные последствия, кроме риска болезни.'
cold=frigid.replace('Мороз наступает при температуре 0° F и ниже. Экспедиционная скорость искателей приключений сокращается вдвое, а собирательство невозможно.','Холод наступает при температуре выше 0° F и ниже 32° F.').replace('более шести ходов','более четырёх часов (24 хода)').replace('В мороз отдых невозможен без защитной одежды или одеял и одновременно костра или другого большого источника тепла.','В холод для отдыха необходима либо защитная одежда, либо одеяла, либо костёр или другой большой источник тепла.').replace('семи дней мороза','семи дней холода').replace('10%','5%')
